def calculate_k(a, b, d, s):
    # A = {0, 1, ..., a-1}
    # B = {s, s+1, ..., s+b-1}
    k = 0
    for m in range(a):
        # |m - n| <= d  => m-d <= n <= m+d
        # n is in {s, ..., s+b-1}
        # So n must be in [max(m-d, s), min(m+d, s+b-1)]
        low = max(m - d, s)
        high = min(m + d, s + b - 1)
        if low <= high:
            k += (high - low + 1)
    return k

a = 2000
b = 2016
d = 1000

# Search for the best s
max_k = 0
best_s = 0
for s in range(-b - d, a + d):
    k = calculate_k(a, b, d, s)
    if k > max_k:
        max_k = k
        best_s = s

print(f"max_k: {max_k}, best_s: {best_s}")
